from django.core.validators import RegexValidator  # Готовый валидатор сравнивает текст с регулярным выражением.
login_validator = RegexValidator(r"\A[A-Za-z0-9]{6,50}\Z", "Логин: от 6 до 50 латинских букв или цифр.")  # \A и \Z требуют совпадения всей строки; {6,50} задаёт длину.
name_validator = RegexValidator(r"\A[А-Яа-яЁё]+(?: [А-Яа-яЁё]+)*\Z", "ФИО: только кириллица и одиночные пробелы между словами.")  # Первая группа — слово, повторяемая группа — пробел и следующее слово.
phone_validator = RegexValidator(r"\A8\([0-9]{3}\)[0-9]{3}-[0-9]{2}-[0-9]{2}\Z", "Телефон строго в формате 8(999)123-45-67.")  # Скобки экранированы, чтобы проверять символы, а не создавать группы.
